/* ============================================================
   SASTOUKASTORE — HEADER CLIENT UNIFIÉ V6
   Réécriture structurelle du haut de /panier et /commande.
   Pas de dépendance aux anciens sélecteurs d'icône.
   ============================================================ */

html, body.p64{
  margin:0 !important;
  padding:0 !important;
  width:100% !important;
  min-width:0 !important;
  overflow-x:hidden !important;
}

body.p64{
  background:#eef3f8 !important;
  color:#07111f !important;
}

/* ---------------- BANDEAU ---------------- */
.ssk6-strip{
  width:100% !important;
  height:30px !important;
  min-height:30px !important;
  box-sizing:border-box !important;
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  padding:0 14px !important;
  overflow:hidden !important;
  background:#050c16 !important;
  color:#dfffa2 !important;
  border-bottom:1px solid rgba(255,255,255,.08) !important;
  font:900 8px/1 Arial,sans-serif !important;
  letter-spacing:1.1px !important;
  text-align:center !important;
  white-space:nowrap !important;
}

/* ---------------- HEADER ---------------- */
.ssk6-header{
  position:sticky !important;
  top:0 !important;
  z-index:2000 !important;
  width:100% !important;
  height:78px !important;
  min-height:78px !important;
  max-height:78px !important;
  box-sizing:border-box !important;
  display:grid !important;
  grid-template-columns:minmax(240px,1fr) auto minmax(170px,1fr) !important;
  align-items:center !important;
  gap:22px !important;
  padding:0 max(18px,calc((100% - 1280px)/2)) !important;
  background:rgba(255,255,255,.98) !important;
  border-bottom:1px solid #dce5ee !important;
  box-shadow:0 8px 24px rgba(7,17,31,.06) !important;
  backdrop-filter:blur(15px) !important;
  overflow:hidden !important;
}

/* ---------------- MARQUE ---------------- */
.ssk6-brand{
  display:flex !important;
  align-items:center !important;
  justify-self:start !important;
  gap:10px !important;
  width:max-content !important;
  max-width:100% !important;
  height:52px !important;
  min-width:0 !important;
  position:relative !important;
  text-decoration:none !important;
  overflow:visible !important;
}

/* Important : l'accès admin discret cible .p64-brand.
   On donne donc aussi cette classe au lien de marque. */
.ssk6-brand.p64-brand{
  display:flex !important;
}

.ssk6-logo-box{
  width:46px !important;
  height:46px !important;
  min-width:46px !important;
  min-height:46px !important;
  max-width:46px !important;
  max-height:46px !important;
  display:grid !important;
  place-items:center !important;
  overflow:hidden !important;
  border-radius:13px !important;
  background:#fff !important;
  border:1px solid #d8e2eb !important;
  box-shadow:0 7px 18px rgba(7,17,31,.08) !important;
  flex:0 0 46px !important;
}

.ssk6-logo{
  display:block !important;
  width:42px !important;
  height:42px !important;
  min-width:42px !important;
  min-height:42px !important;
  max-width:42px !important;
  max-height:42px !important;
  flex:0 0 42px !important;
  object-fit:contain !important;
  object-position:center !important;
  position:static !important;
  inset:auto !important;
  margin:0 !important;
  padding:0 !important;
  float:none !important;
  transform:none !important;
}

.ssk6-brand-name{
  display:block !important;
  min-width:0 !important;
  max-width:230px !important;
  color:#07111f !important;
  font:1000 18px/1.04 Arial,sans-serif !important;
  letter-spacing:.1px !important;
  white-space:nowrap !important;
}

.ssk6-brand-name small{
  display:block !important;
  margin-top:3px !important;
  color:#8795a5 !important;
  font:800 8px/1 Arial,sans-serif !important;
  letter-spacing:1.25px !important;
}

/* ---------------- NAVIGATION ---------------- */
.ssk6-nav{
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  gap:27px !important;
  min-width:0 !important;
  white-space:nowrap !important;
}

.ssk6-nav a{
  display:inline-flex !important;
  align-items:center !important;
  color:#4f6074 !important;
  font:950 11px/1 Arial,sans-serif !important;
  text-decoration:none !important;
  padding:10px 4px !important;
}

.ssk6-nav a:hover{
  color:#07111f !important;
}

/* ---------------- ACTIONS ---------------- */
.ssk6-actions{
  display:flex !important;
  align-items:center !important;
  justify-content:flex-end !important;
  gap:8px !important;
  min-width:0 !important;
}

.ssk6-wa{
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  min-height:42px !important;
  padding:0 14px !important;
  box-sizing:border-box !important;
  border:1px solid #d3dfeb !important;
  border-radius:11px !important;
  background:#fff !important;
  color:#07111f !important;
  font:1000 10px/1 Arial,sans-serif !important;
  text-decoration:none !important;
}

.ssk6-cart{
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  gap:7px !important;
  min-width:112px !important;
  min-height:43px !important;
  padding:0 12px !important;
  box-sizing:border-box !important;
  border:1px solid #07111f !important;
  border-radius:12px !important;
  background:#07111f !important;
  color:#fff !important;
  font:1000 10px/1 Arial,sans-serif !important;
  text-decoration:none !important;
  box-shadow:0 8px 20px rgba(7,17,31,.12) !important;
}

.ssk6-count{
  display:inline-grid !important;
  place-items:center !important;
  min-width:20px !important;
  height:20px !important;
  padding:0 5px !important;
  box-sizing:border-box !important;
  border-radius:999px !important;
  background:#7bef42 !important;
  color:#07111f !important;
  font:1000 9px/1 Arial,sans-serif !important;
}

/* ---------------- ESPACE SOUS HEADER ---------------- */
body.p64 > main.p64-wrap,
body.p64 > main.pp-wrap{
  margin-top:0 !important;
}

/* ---------------- FILET DE SÉCURITÉ ----------------
   Une ancienne image hors header ne doit jamais occuper la page. */
body.p64 > img.chariow-header-logo,
body.p64 > img.chariow-brand-icon,
body.p64 > img.chariow-force-icon,
body.p64 > .chariow-header-logo,
body.p64 > .chariow-brand-icon,
body.p64 > .brand-mark,
body.p64 > .brand-logo,
body.p64 > .logo-mark,
body.p64 > .site-logo{
  display:none !important;
  width:0 !important;
  height:0 !important;
  max-width:0 !important;
  max-height:0 !important;
}

/* ---------------- MOBILE ---------------- */
@media(max-width:850px){
  .ssk6-header{
    height:70px !important;
    min-height:70px !important;
    max-height:70px !important;
    grid-template-columns:1fr auto !important;
    gap:10px !important;
    padding:0 12px !important;
  }

  .ssk6-nav{
    display:none !important;
  }

  .ssk6-brand{
    height:48px !important;
  }

  .ssk6-logo-box{
    width:42px !important;
    height:42px !important;
    min-width:42px !important;
    min-height:42px !important;
    max-width:42px !important;
    max-height:42px !important;
    flex-basis:42px !important;
  }

  .ssk6-logo{
    width:39px !important;
    height:39px !important;
    min-width:39px !important;
    min-height:39px !important;
    max-width:39px !important;
    max-height:39px !important;
    flex-basis:39px !important;
  }

  .ssk6-brand-name{
    font-size:16px !important;
  }

  .ssk6-brand-name small{
    font-size:7px !important;
  }

  .ssk6-wa{
    display:none !important;
  }

  .ssk6-cart{
    min-width:92px !important;
    min-height:40px !important;
  }
}

@media(max-width:460px){
  .ssk6-strip{
    font-size:6.5px !important;
    letter-spacing:.55px !important;
  }

  .ssk6-brand-name{
    font-size:15px !important;
  }

  .ssk6-cart{
    min-width:82px !important;
    padding:0 9px !important;
  }
}

