/* SASTOUKASTORE — FICHE PRODUIT / APERÇU PDF */
.p62-cover-stage{
  min-height:640px !important;
  padding:22px !important;
  align-items:center !important;
  justify-content:center !important;
}
.p62-cover-sheet{
  width:min(100%,380px) !important;
  aspect-ratio:210 / 297 !important;
  height:auto !important;
  max-height:78vh !important;
  border-radius:4px !important;
  background:#fff !important;
  overflow:hidden !important;
}
.p62-cover-sheet img{
  display:block !important;
  width:100% !important;
  height:100% !important;
  object-fit:contain !important;
  object-position:center !important;
  background:#fff !important;
}
.ssk-preview-launch{
  margin:18px 0 0;
  padding:15px 16px;
  border:1px solid #dce4ec;
  border-radius:16px;
  background:linear-gradient(135deg,#f8fafc,#ffffff);
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:16px;
  box-shadow:0 12px 30px rgba(7,17,31,.06);
}
.ssk-preview-copy{min-width:0}
.ssk-preview-copy strong{display:block;color:#101827;font-size:14px;line-height:1.25}
.ssk-preview-copy span{display:block;margin-top:5px;color:#738091;font-size:10px;line-height:1.45}
.ssk-preview-btn{
  flex:0 0 auto;
  min-height:45px;
  padding:0 16px;
  border:0;
  border-radius:11px;
  background:linear-gradient(135deg,#ff7900,#ff9c32);
  color:#fff;
  font-size:11px;
  font-weight:1000;
  cursor:pointer;
  box-shadow:0 10px 24px rgba(255,121,0,.22);
}
.ssk-preview-btn:hover{
  background:linear-gradient(135deg,#d52f1d,#ff7900);
  transform:translateY(-1px);
}
.ssk-preview-modal[hidden]{display:none !important}
.ssk-preview-modal{
  position:fixed;
  inset:0;
  z-index:9999;
  padding:20px;
  background:rgba(4,10,18,.82);
  backdrop-filter:blur(9px);
  overflow:auto;
}
.ssk-preview-dialog{
  width:min(1180px,100%);
  margin:0 auto;
  background:#f5f7fa;
  border:1px solid rgba(255,255,255,.15);
  border-radius:20px;
  box-shadow:0 30px 80px rgba(0,0,0,.32);
  overflow:hidden;
}
.ssk-preview-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:15px;
  padding:18px 20px;
  background:#08111f;
  color:#fff;
}
.ssk-preview-head strong{display:block;font-size:15px}
.ssk-preview-head span{display:block;margin-top:4px;color:#aab7c5;font-size:9px;line-height:1.4}
.ssk-preview-close{
  width:38px;
  height:38px;
  border:1px solid rgba(255,255,255,.18);
  border-radius:10px;
  background:rgba(255,255,255,.05);
  color:#fff;
  font-size:20px;
  cursor:pointer;
}
.ssk-preview-pages{
  padding:18px;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:16px;
  align-items:start;
}
.ssk-preview-page{
  margin:0;
  background:#fff;
  border:1px solid #dfe6ee;
  border-radius:5px;
  overflow:hidden;
  box-shadow:0 16px 35px rgba(7,17,31,.12);
  position:relative;
}
.ssk-preview-page img{
  display:block;
  width:100%;
  height:auto;
  aspect-ratio:210 / 297;
  object-fit:contain;
  background:#fff;
}
.ssk-preview-caption{
  padding:8px 10px;
  font-size:9px;
  font-weight:900;
  letter-spacing:.5px;
  color:#697789;
  border-top:1px solid #edf1f4;
  text-align:center;
}
.ssk-preview-foot{
  padding:12px 18px 16px;
  color:#7a8795;
  font-size:9px;
  line-height:1.5;
  text-align:center;
}
@media(max-width:900px){
  .ssk-preview-pages{grid-template-columns:1fr 1fr}
  .p62-cover-stage{min-height:500px !important}
}
@media(max-width:640px){
  .ssk-preview-launch{align-items:stretch;flex-direction:column}
  .ssk-preview-btn{width:100%}
  .ssk-preview-modal{padding:9px}
  .ssk-preview-head{padding:13px 14px}
  .ssk-preview-pages{grid-template-columns:1fr;padding:11px}
  .ssk-preview-page{width:min(100%,430px);margin:0 auto}
  .p62-cover-sheet{width:min(100%,300px) !important}
}
@media(max-width:480px){
  .p62-cover-stage{min-height:420px !important;padding:12px !important}
}

