}

/* --- LE RÉSUMÉ (Panneau de droite ultra-agressif pour la conversion) --- */
body.p64 .p64-summary {
  position: sticky !important;
  top: 90px !important;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%) !important;
  border: 2px solid var(--cart-vip-navy) !important;
  border-radius: 20px !important;
  box-shadow: 0 15px 40px rgba(13, 33, 56, 0.12) !important;
  padding: 30px !important;
}

body.p64 .p64-summary .p64-kicker {
  color: var(--cart-vip-navy) !important;
  font-weight: 900 !important;
  font-size: 11px !important;
