}

body.p64 .p64-total strong {
  color: var(--cart-vip-action) !important;
  font-size: 36px !important;
  line-height: 1 !important;
  letter-spacing: -1px !important;
}

/* Bouton d'action "Passer la commande" (Pulsation) */
body.p64 .p64-summary .p64-primary {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: linear-gradient(135deg, var(--cart-vip-action), #ff9e38) !important;
  color: #fff !important;
  font-size: 15px !important;
  font-weight: 900 !important;
  height: 56px !important;
  border-radius: 14px !important;
  animation: cart-pulse 2s infinite !important;
  border: none !important;
  margin-top: 25px !important;
  text-transform: uppercase !important;
  letter-spacing: 0.5px !important;
