/* ============================================================
   SASTOUKASTORE — VIP GLOBAL CLIENT + ADMIN V1
   Couche visuelle globale uniquement.
   Aucun contenu métier, produit, prix, paiement ou SQLite.
   ============================================================ */

:root{
  --ssk-ink:#07111f;
  --ssk-navy:#10243b;
  --ssk-blue:#0b63c7;
  --ssk-blue2:#1678dc;
  --ssk-orange:#ff7600;
  --ssk-orange2:#ff9e38;
  --ssk-green:#7bef42;
  --ssk-bg:#eef3f8;
  --ssk-card:#ffffff;
  --ssk-line:#dce5ee;
  --ssk-muted:#718197;
}

/* ===== 1. RESET VISUEL DE BASE ===== */
html,body{
  min-width:0 !important;
  max-width:100% !important;
  overflow-x:hidden !important;
}

body{
  color:var(--ssk-ink);
}

/* ===== 2. LOGO : verrouillage global =====
   Neutralise les anciennes règles qui forçaient l'image à 100%.
*/
header img.chariow-header-logo,
header img.chariow-brand-icon,
header .chariow-header-logo,
.topbar img.chariow-header-logo,
.premium-nav img.chariow-header-logo,
.vip-nav img.chariow-header-logo,
.p64-nav img.chariow-header-logo,
.p64-brand img.chariow-brand-icon,
.p64-brand img.chariow-header-logo,
.premium-brand img.chariow-brand-icon,
.premium-brand img.chariow-header-logo{
  display:block !important;
  width:42px !important;
  height:42px !important;
  min-width:42px !important;
  min-height:42px !important;
  max-width:42px !important;
  max-height:42px !important;
  flex:0 0 42px !important;
  position:static !important;
  inset:auto !important;
  float:none !important;
  transform:none !important;
  object-fit:contain !important;
  object-position:center !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
}

/* Parents de logo */
.p64-brand,
.premium-brand,
.topbar .brand,
.vip-brand{
  min-width:0 !important;
  max-width:360px !important;
  overflow:visible !important;
