/* ============================================================
   SASTOUKASTORE — GLOBAL VIP / ICON SAFETY V2
   Corrige définitivement les logos/images géantes causées par
   les anciens injecteurs d'icône.
   ============================================================ */

:root{
  --ssk-ink:#07111f;
  --ssk-blue:#0b63c7;
  --ssk-orange:#ff7600;
  --ssk-green:#7bef42;
  --ssk-line:#dce5ee;
}

/* ---------- VERROUILLAGE GLOBAL DES LOGOS ---------- */
html body img.chariow-header-logo,
html body img.chariow-brand-icon,
html body .chariow-header-logo,
html body .chariow-brand-icon{
  display:block !important;
  width:42px !important;
  height:42px !important;
  min-width:42px !important;
  min-height:42px !important;
  max-width:42px !important;
  max-height:42px !important;
  flex:0 0 42px !important;
  object-fit:contain !important;
  object-position:center !important;
  position:static !important;
  inset:auto !important;
  transform:none !important;
  float:none !important;
  margin:0 !important;
  padding:0 !important;
  visibility:visible !important;
  opacity:1 !important;
}

/* ---------- CONTENEURS DE MARQUE ---------- */
html body .vip-brand,
html body .premium-brand,
html body .p64-brand,
html body .brand,
html body .topbar .brand{
  display:flex !important;
  align-items:center !important;
  gap:10px !important;
  width:auto !important;
  min-width:0 !important;
  max-width:360px !important;
  height:auto !important;
  max-height:58px !important;
  flex:0 0 auto !important;
  position:relative !important;
  overflow:visible !important;
}

/* Les anciens injecteurs mettaient l'image en background du conteneur.
   Nous neutralisons ces backgrounds sans supprimer le logo réel <img>. */
html body .vip-brand-mark,
html body .premium-brand .brand-mark,
html body .premium-brand .brand-logo,
html body .p64-brand-mark,
html body .brand-mark,
html body .brand-logo{
  background-image:none !important;
