(function () {
  "use strict";

  var REQUIRED_CLICKS = 7;
  var WINDOW_MS = 5000;
  var clicks = 0;
  var timer = null;
  var activeElement = null;

  function reset() {
    clicks = 0;

    if (timer) {
      clearTimeout(timer);
      timer = null;
    }

    activeElement = null;
  }

  function findLogoTarget(target) {
    if (!target || !target.closest) return null;

    /*
      On cible uniquement le logo / bloc de marque de l'en-tête.
      Aucun compteur, contour, cadenas ou message n'est injecté.
    */
    var el = target.closest(
      ".vip-brand,.premium-brand,.p64-brand,.brand"
    );

    if (el) return el;

    var img = target.closest("img.sastoukastore-header-logo");
    if (img) return img;

    return null;
  }

  function openAdmin(ev) {
    reset();

    if (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      ev.stopImmediatePropagation();
    }

    window.location.href = "/admin/login?next=/admin/dashboard";
  }

  function handleClick(ev) {
    var logo = findLogoTarget(ev.target);
    if (!logo) return;

    /*
      Le logo reste visuellement parfaitement normal.
      Le clic normal sur le logo est neutralisé afin de compter la séquence.
    */
    ev.preventDefault();
    ev.stopPropagation();

    if (activeElement && activeElement !== logo) {
      reset();
    }

    activeElement = logo;

    clicks += 1;

    if (clicks === 1) {
      timer = window.setTimeout(reset, WINDOW_MS);
    } else if (timer) {
      clearTimeout(timer);
      timer = window.setTimeout(reset, WINDOW_MS);
    }

    if (clicks >= REQUIRED_CLICKS) {
      openAdmin(ev);
    }
  }

  function removeOldVisibleAccess() {
    var ids = [
      "sastoukastoreAdminAccess22",
      "sastoukastoreAdminTrigger"
    ];

    ids.forEach(function (id) {
      var el = document.getElementById(id);
      if (el) el.remove();
    });

    document.querySelectorAll(
      ".sastoukastore-admin-access-22," +
      ".sastoukastore-admin-trigger," +
      ".sastoukastore-admin-logo-indicator"
    ).forEach(function (el) {
      el.remove();
    });

    /*
      Supprime également les styles/éléments issus des anciennes versions.
    */
    var oldStyle = document.getElementById("sastoukastoreAdmin7ClicksStyle");
    if (oldStyle) oldStyle.remove();
    var oldStyle22 = document.getElementById("sastoukastoreAdminAccess22Style");
    if (oldStyle22) oldStyle22.remove();
  }

  function init() {
    removeOldVisibleAccess();

    /*
      Capture phase pour fonctionner même si le header est recréé
      dynamiquement par un autre script.
    */
    document.addEventListener("click", handleClick, true);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

let deferredPrompt=null;
const installBtn=document.getElementById("installBtn");
window.addEventListener("beforeinstallprompt",(event)=>{event.preventDefault();deferredPrompt=event;if(installBtn)installBtn.hidden=false});
if(installBtn){installBtn.addEventListener("click",async()=>{if(!deferredPrompt)return;deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;installBtn.hidden=true})}
window.addEventListener("appinstalled",()=>{if(installBtn)installBtn.hidden=true});
if("serviceWorker" in navigator){window.addEventListener("load",()=>{navigator.serviceWorker.register("/static/sw.js").catch(console.error)})}
document.querySelectorAll(".product-footer button").forEach((button)=>{button.addEventListener("click",()=>{const badge=document.getElementById("cartBadge");if(badge)badge.textContent=Number(badge.textContent||0)+1})});

(function(){
const KEY="sastoukastore_cart_v1";
function read(){try{const x=JSON.parse(localStorage.getItem(KEY)||"[]");return Array.isArray(x)?x:[]}catch(e){return[]}}
function save(x){localStorage.setItem(KEY,JSON.stringify(x));badge()}
function money(x){return new Intl.NumberFormat("fr-FR",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(x)||0)+" FCFA"}
function badge(){const n=read().reduce((s,x)=>s+Number(x.quantity||0),0);document.querySelectorAll("#cartBadge,#cartBadgeMobile").forEach(e=>e.textContent=n)}
function total(c){return c.reduce((s,x)=>s+Number(x.price)*Number(x.quantity),0)}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]))}
function notice(t){let b=document.getElementById("cartNotice");if(!b){b=document.createElement("div");b.id="cartNotice";b.className="cart-notice";document.body.appendChild(b)}b.textContent=t;b.classList.add("show");setTimeout(()=>b.classList.remove("show"),1800)}
window.addProductToCart=function(p){const q=Math.max(1,Number(document.getElementById("productQty")?.value||1)),c=read(),x=c.find(i=>Number(i.id)===Number(p.id));if(x)x.quantity+=q;else c.push({id:Number(p.id),name:String(p.name),price:Number(p.price),image:String(p.image||""),quantity:q});save(c);notice("Produit ajouté au panier.")};
window.changeCartQuantity=function(id,d){const c=read(),x=c.find(i=>Number(i.id)===Number(id));if(!x)return;x.quantity=Math.max(1,Number(x.quantity)+d);save(c);renderCart();renderCheckout()};
window.removeCartItem=function(id){save(read().filter(x=>Number(x.id)!==Number(id)));renderCart();renderCheckout()};
function renderCart(){const box=document.getElementById("cartItems");if(!box)return;const c=read(),empty=document.getElementById("cartEmpty"),content=document.getElementById("cartContent");if(!c.length){empty.hidden=false;content.style.display="none";return}empty.hidden=true;content.style.display="grid";box.innerHTML=c.map(x=>`<article class="cart-item"><div class="cart-item-image">${x.image?`<img src="${esc(x.image)}" alt="">`:"SastoukaStore"}</div><div class="cart-item-info"><h3>${esc(x.name)}</h3><strong>${money(x.price)}</strong><div class="cart-item-actions"><div class="mini-qty"><button onclick="changeCartQuantity(${x.id},-1)">−</button><span>${x.quantity}</span><button onclick="changeCartQuantity(${x.id},1)">+</button></div><button class="remove-btn" onclick="removeCartItem(${x.id})">Supprimer</button></div></div><strong class="cart-line-total">${money(x.price*x.quantity)}</strong></article>`).join("");document.getElementById("cartSubtotal").textContent=money(total(c));document.getElementById("cartTotal").textContent=money(total(c))}
function renderCheckout(){const box=document.getElementById("checkoutItems");if(!box)return;const c=read(),empty=document.getElementById("checkoutEmpty"),content=document.getElementById("checkoutContent");if(!c.length){empty.hidden=false;content.style.display="none";return}empty.hidden=true;content.style.display="grid";box.innerHTML=c.map(x=>`<div class="checkout-line"><span>${esc(x.name)} × ${x.quantity}</span><strong>${money(x.price*x.quantity)}</strong></div>`).join("");document.getElementById("checkoutTotal").textContent=money(total(c))}
const form=document.getElementById("checkoutForm");
if(form)form.addEventListener("submit",async e=>{e.preventDefault();const c=read();if(!c.length)return;const btn=document.getElementById("submitOrder"),err=document.getElementById("checkoutError");err.hidden=true;btn.disabled=true;btn.textContent="Enregistrement…";const f=new FormData(form);try{const r=await fetch("/api/commande",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({customer:{name:f.get("name"),phone:f.get("phone"),email:f.get("email"),address:f.get("address"),city:f.get("city")},items:c,payment_method:f.get("payment_method"),notes:f.get("notes")})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||"Erreur");localStorage.removeItem(KEY);badge();document.getElementById("checkoutContent").style.display="none";document.getElementById("checkoutSuccess").hidden=false;document.getElementById("successOrderId").textContent="#"+d.order_id}catch(x){err.textContent=x.message;err.hidden=false;btn.disabled=false;btn.textContent="Confirmer la commande"}});
document.addEventListener("DOMContentLoaded",()=>{badge();renderCart();renderCheckout()});
})();
